struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

float sdBox(float2 p, float2 b)
{
    float2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

float4 PSShadowDepth(VSOut i) : SV_Target
{
    float2 uv = i.uv;
    float t = time_sim_ms * 0.001;
    float2 boxCenter = float2(0.5 + 0.15 * sin(t), 0.4);
    float d = sdBox(uv - boxCenter, float2(0.1, 0.1));
    float depth = d < 0.0 ? 0.3 : 1.0;
    return float4(depth, depth, depth, 1.0);
}

