[[vk::combinedImageSampler]] [[vk::binding(0, 2)]]
Texture2D shadowTex : register(t0, space2);
[[vk::combinedImageSampler]] [[vk::binding(0, 2)]]
SamplerState shadowSamp : register(s0, space2);

struct VSOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };

float4 PSLit(VSOut i) : SV_Target
{
    float2 uv = i.uv;
    float t = time_sim_ms * 0.001;
    float2 lightPos = float2(0.5 + 0.2 * cos(t * 0.5), 0.1);
    float2 lightDir = normalize(lightPos - uv);

    float shadow = shadowTex.Sample(shadowSamp, uv).r;
    float inShadow = shadow < 0.9 ? 0.3 : 1.0;

    float3 groundColor = float3(0.4, 0.6, 0.3);
    float diffuse = saturate(dot(float2(0, -1), lightDir));
    float3 color = groundColor * (diffuse * inShadow * 0.7 + 0.3);

    float2 boxCenter = float2(0.5 + 0.15 * sin(t), 0.4);
    if (abs(uv.x - boxCenter.x) < 0.1 && abs(uv.y - boxCenter.y) < 0.1)
        color = float3(0.8, 0.3, 0.2);

    return float4(color, 1.0);
}
